const { owner, gatekeeperApiUrl } = input;
const orgRes = await fetch(`${gatekeeperApiUrl}/api/organization/by-slug/${owner}`, {
  headers: { 'Content-Type': 'application/json' }
});
if (!orgRes.ok) {
  console.error(`[fractal-email] org lookup failed for ${owner}: ${orgRes.status}`);
  return { recipients: [] };
}
const org = await orgRes.json();
const membersRes = await fetch(`${gatekeeperApiUrl}/api/organization/members?orgId=${org.id}`, {
  headers: { 'Content-Type': 'application/json' }
});
if (!membersRes.ok) {
  console.error(`[fractal-email] members lookup failed for org ${org.id}: ${membersRes.status}`);
  return { recipients: [] };
}
const { data: members } = await membersRes.json();
console.log(`[fractal-email] resolved ${members.length} recipients for ${owner}`);
return { recipients: members.map(m => m.user.email) };

const { recipients, eventType, service, project, owner, phase, image, commit, memory_limit, memory_usage, fractalAppUrl, emailRenderSecret, heraldUrl, heraldKey, heraldSender, senderAddress, vortexApiUrl, vortexApiKey } = input;
if (!recipients || recipients.length === 0) return { sent: 0 };
if (!heraldUrl || !heraldKey) {
  console.error('[fractal-email] Herald not configured');
  return { sent: 0, reason: 'no-email-provider' };
}

let templateId;
if (eventType.includes('build.failed')) templateId = 'build-failed';
else if (eventType.includes('deploy.succeeded')) templateId = 'deploy-succeeded';
else if (eventType.includes('service.crashed')) templateId = 'service-crashed';
else if (eventType.includes('service.resource_warning')) templateId = 'resource-warning';
else return { sent: 0, reason: 'unknown event type' };

const fractalUrl = `${fractalAppUrl}/workspaces/${owner}/projects/${project}/services/${service}`;
const templateData = { serviceName: service, projectName: project, commitSha: commit, fractalUrl, imageTag: image?.split(':').pop() };
if (memory_limit) templateData.memoryLimit = memory_limit;
if (memory_usage) templateData.memoryUsage = memory_usage;

const from = heraldSender || senderAddress || 'notifications@send.omni.dev';
let sent = 0;
for (const email of recipients) {
  const suppRes = await fetch(vortexApiUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${vortexApiKey}` },
    body: JSON.stringify({ query: `query($email:String!){emailSuppressions(condition:{email:$email}){totalCount}}`, variables: { email } })
  });
  const suppJson = await suppRes.json();
  if ((suppJson.data?.emailSuppressions?.totalCount ?? 0) > 0) continue;

  const renderRes = await fetch(`${fractalAppUrl}/api/email/render`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${emailRenderSecret}` },
    body: JSON.stringify({ templateId, templateData })
  });
  if (!renderRes.ok) {
    const body = await renderRes.text().catch(() => '');
    console.error(`[fractal-email] render failed for ${email}: ${renderRes.status} ${body}`);
    continue;
  }
  const { html, subject } = await renderRes.json();

  const sendRes = await fetch(`${heraldUrl}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${heraldKey}` },
    body: JSON.stringify({ to: email, from, subject: `${subject} - ${service}`, html, idempotencyKey: `${eventType}:${service}:${commit || phase || 'na'}:${email}` })
  });
  if (!sendRes.ok) {
    const body = await sendRes.text().catch(() => '');
    console.error(`[fractal-email] herald failed for ${email}: ${sendRes.status} ${body}`);
    continue;
  }
  sent++;
}
return { sent };
